from pathlib import Path
from html import escape
import json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'DIRECAO-BORDO'
def im(src,cls=''):return f'<img src="{src}" class="{cls}" alt="{escape(Path(src).stem)}">'
pages=[]
def page(id,kicker,title,body,cls=''):
 n=len(pages)+1
 pages.append(f'<div class="sheet" id="{id}"><section class="page {cls}"><div class="inner"><header>{kicker}</header>'+ (f'<h1>{title}</h1>' if title else '')+body+f'</div><footer><span>AUREVI · DIREÇÃO VISUAL EM ESTUDO</span><span>04/11/2026 &nbsp; / &nbsp; {n:02}</span></footer></section></div>')

page('capa','AUREVI / APRESENTAÇÃO DE DIREÇÃO','',f'''
<div class="hero-left"><div class="kicker">MODA FEMININA · PROPOSTA PARA A MARCA</div>{im('logos/AV-ouro.svg','hero-symbol')}{im('logos/AUREVI-assinatura-marfim.svg','hero-word')}<div class="hero-tag">Ouro no nome.<br>Vida no estilo.</div><p>Uma direção em bordô, dourado e marfim.</p></div>
<div class="hero-photo">{im('editorial/vestido-bordo.png')}<span>ESTUDO EDITORIAL · IMAGEM GERADA POR IA</span></div>''','cover')

page('cores','01 / OURO + VIDA','Uma paleta com presença.',f'''
<div class="palette"><div class="swatch wine"><span>01 / BASE</span><h2>Bordô</h2><b>#681E36</b><p>Presença, feminilidade e profundidade.</p></div><div class="swatch gold"><span>02 / DETALHE</span><h2>Ouro champagne</h2><b>#CFB77F</b><p>Uma ligação com “Aure” nos detalhes e na assinatura.</p></div><div class="swatch ivory"><span>03 / RESPIRO</span><h2>Marfim</h2><b>#FAF6EF</b><p>Leitura clara e espaço para valorizar a roupa.</p></div></div>
<div class="two notes"><div><h2>Aure · ouro</h2><p>O dourado pode aparecer no símbolo, em uma linha de acabamento, em metais ou na embalagem.</p></div><div><h2>Vi · vida</h2><p>Vida no movimento da roupa, na mulher que veste e nas ocasiões que ela escolhe viver.</p></div></div><p class="small">Códigos propostos a partir da referência enviada. Tecido fotografado e luz mudam a aparência da cor; o acabamento metálico precisa de material e prova próprios.</p>''')

page('simbolo','02 / O AV GANHA UM NOVO ACABAMENTO','Duas formas de assinar a Aurevi.',f'''
<div class="two symbols"><article><div class="symbol-panel">{im('logos/AV-ouro.svg')}</div><h2>01 · AV com contraste</h2><p>Diagonais separadas, diferença entre traços finos e grossos e terminações curvas. As iniciais ficam mais explícitas.</p></article><article><div class="symbol-panel">{im('logos/AV-gesto-ouro.svg')}</div><h2>02 · AV em gesto</h2><p>Curvas contínuas e linhas mais finas. Uma leitura abstrata, próxima de uma assinatura ou de um detalhe bordado.</p></article></div><p class="small">Estudos desenhados para a Aurevi a partir da linguagem das referências. O primeiro favorece reconhecimento das iniciais; o segundo pede avaliação de reconhecimento em tamanhos pequenos.</p>''')

options=[('01-editorial','01 · Editorial','Contraste alto e presença de moda. O traço fino exige cuidado nas reduções.'),('02-assinatura','02 · Assinatura — minha sugestão','Serifas elegantes, espaçamento trabalhado e um gesto no R para acrescentar personalidade.'),('03-contemporanea','03 · Contemporânea','Desenho alongado e leve, com formas particulares no A e no V.')]
rows=''.join(f'<article class="word-row"><div>{im("logos/"+file+"-bordo.svg")}</div><div><h2>{title}</h2><p>{desc}</p></div></article>' for file,title,desc in options)
page('escrita','03 / O NOME TAMBÉM PRECISA TER CHARME','A escrita completa a assinatura.',f'<div class="word-rows">{rows}</div><p class="small">Três estudos para comparar na mesma paleta. O desenho do nome e a escolha entre os dois AV ainda estão em avaliação; esta apresentação não pressupõe aprovação das sócias.</p>')

mockups=json.loads((OUT/'mockups/links.json').read_text(encoding='utf-8'))
cards=''.join(f'<figure>{im("mockups/"+m["filename"])}<figcaption><a href="{escape(m["editUrl"],quote=True)}">{label} · Kittl ↗</a></figcaption></figure>' for m,label in zip(mockups,['Sacola estruturada com alça de cordão','Aplicação da escrita em papel claro']))
page('aplicacoes','04 / UMA EXPERIÊNCIA DE LOJA DE ROUPAS','A marca encontra a boutique.',f'<div class="mockups">{cards}<figure class="tag">{im("tag-estudo.svg")}<figcaption>Tag em bordô, ouro e marfim.</figcaption></figure></div><p class="small">Mockups renderizados no Kittl com a escrita 02. A tag é um estudo plano de aplicação. Para produção, definir papel, medidas e acabamento com o fornecedor.</p>')

page('fotografia','05 / A ROUPA ORIENTA A IMAGEM','O estilo aparece no caimento.',f'''
<div class="photo-layout"><figure>{im('editorial/vestido-bordo.png')}<figcaption>Estudo editorial gerado por IA a partir da referência enviada.</figcaption></figure><div><h2>Feminino e produzido</h2><p>Vestido ajustado, drapeado lateral, fenda e acessórios. Uma imagem que apresenta a construção e a presença do look.</p><h2>Cenário e modelo</h2><p>Modelo diferente da referência inicial, fundo liso de estúdio e luz limpa. O vestido foi alterado para bordô para conversar com a paleta.</p><h2>Direção para o catálogo real</h2><p>A amostra da Donna reúne jeans, conjuntos e vestidos mais produzidos. A Aurevi pode mostrar essa variedade com fotos de roupa real, planos de caimento e detalhes.</p><p class="small">Esta imagem é um estudo para apresentação. Na venda, conferir cor, tecido, modelagem e acabamento com o produto real.</p></div></div>''')

page('sintese','06 / PARA A CONVERSA ENTRE AS SÓCIAS','O conjunto que proponho.',f'''
<div class="two final"><div class="final-brand">{im('logos/AV-ouro.svg')}{im('logos/AUREVI-assinatura-marfim.svg')}<div class="color-bars"><i></i><i></i><i></i></div></div><div><h2>Bordô + ouro champagne</h2><p>A direção de cores vem da preferência apresentada. O marfim mantém o sistema leve e legível.</p><h2>Escrita 02 + AV 01</h2><p>Minha recomendação inicial combina o gesto no R com o AV de traços contrastantes. O AV 02 fica como alternativa mais abstrata para comparar.</p><h2>O que decidir juntas</h2><p>Qual escrita representa melhor a marca e qual AV fica mais reconhecível para vocês. A partir dessas escolhas, aplicar a direção nos posts e no restante do kit.</p><p class="small">Referências de produto: <a href="https://www.instagram.com/donna.oficial/">Donna no Instagram</a> e <a href="https://www.lojadonnaoficial.com.br/">catálogo Donna</a>, amostra pública consultada com Playwright em 04/11/2026. Fotos da concorrente não compõem esta apresentação.</p></div></div>''')

css='''@font-face{font-family:M;src:url('fontes/Manrope.ttf');font-weight:200 800}@font-face{font-family:C;src:url('fontes/CormorantGaramond.ttf');font-weight:300 700}*{box-sizing:border-box}body{margin:0;background:#e4dbd9;color:#681e36;font:24px/1.5 M,sans-serif}a{color:inherit;text-underline-offset:4px}nav{height:64px;background:#681e36;color:#faf6ef;position:sticky;top:0;z-index:10;padding:0 30px;display:flex;align-items:center;gap:24px;font-size:14px}nav b{letter-spacing:3px}nav a{text-decoration:none}.grow{flex:1}main{padding:28px}.sheet{position:relative;width:calc(1800px * var(--s,1));height:calc(1100px * var(--s,1));margin:0 auto 28px}.page{width:1800px;height:1100px;position:absolute;transform:scale(var(--s,1));transform-origin:0 0;background:#faf6ef;overflow:hidden}.inner{padding:65px 85px 85px}header{font-size:17px;letter-spacing:3px;font-weight:500}h1{font:500 78px/1.08 C,serif;letter-spacing:-1px;margin:20px 0 34px}h2{font:500 41px/1.12 C,serif;margin:8px 0 20px}p{font-size:26px;line-height:1.5;margin:0 0 26px}.small{font-size:21px;line-height:1.5;margin-top:24px}img{display:block;max-width:100%}footer{position:absolute;left:85px;right:85px;bottom:28px;border-top:1px solid #681e3630;padding-top:14px;font-size:13px;letter-spacing:1.5px;display:flex;justify-content:space-between}.two{display:grid;grid-template-columns:1fr 1fr;gap:75px}.cover{background:#681e36;color:#faf6ef}.cover .inner{padding:0}.cover header{display:none}.hero-left{position:absolute;left:80px;top:65px;width:930px}.kicker{color:#cfb77f;font-size:17px;letter-spacing:3px}.hero-symbol{width:270px;margin:65px auto 15px}.hero-word{width:900px;margin-top:14px}.hero-tag{font:500 71px/1.08 C;margin-top:8px}.hero-left p{font-size:23px;color:#e7d7cb;margin-top:30px}.hero-photo{position:absolute;right:0;top:0;width:700px;height:1100px;background:#efeae5}.hero-photo>img{width:100%;height:1100px;object-fit:cover;object-position:center}.hero-photo>span{position:absolute;bottom:28px;left:30px;right:30px;background:#faf6efdf;color:#681e36;padding:10px 12px;font-size:15px;letter-spacing:1px;text-align:center}.cover footer{right:780px;color:#cfb77f;border-color:#cfb77f50}.palette{display:grid;grid-template-columns:1.2fr 1fr 1fr;gap:22px;height:440px}.swatch{padding:32px 30px;display:flex;flex-direction:column;justify-content:flex-end}.swatch>span{font-size:16px;letter-spacing:2px}.swatch h2{font-size:52px;margin:18px 0 12px}.swatch>b{font-size:22px}.swatch>p{font-size:22px;margin:18px 0 0;line-height:1.4}.wine{background:#681e36;color:#faf6ef}.gold{background:#cfb77f;color:#2d1a22}.ivory{background:#faf6ef;border:1px solid #681e3620}.notes{margin-top:42px}.notes p{font-size:25px}.symbols{gap:55px}.symbol-panel{height:500px;background:#681e36;padding:15px 60px}.symbol-panel img{height:100%;width:100%;object-fit:contain}.symbols h2{margin-top:25px}.symbols p{font-size:25px}.word-rows{display:grid;gap:10px}.word-row{height:230px;border-top:1px solid #681e3620;display:grid;grid-template-columns:1040px 1fr;gap:65px;align-items:center}.word-row img{width:100%;height:210px;object-fit:contain}.word-row h2{font-size:35px;margin:0 0 15px}.word-row p{font-size:22px;margin:0}.mockups{display:grid;grid-template-columns:650px 650px 1fr;gap:30px}.mockups img{height:630px;width:100%;object-fit:contain}.mockups .tag img{height:550px;margin-top:40px}.mockups figcaption{font-size:18px;margin-top:15px}figure{margin:0}.photo-layout{display:grid;grid-template-columns:620px 1fr;gap:85px}.photo-layout figure img{height:765px;width:100%;object-fit:contain}.photo-layout figcaption{font-size:19px;max-width:590px;margin-top:12px}.photo-layout h2{margin:10px 0 20px}.photo-layout p{font-size:26px}.final-brand{background:#681e36;display:flex;flex-direction:column;align-items:center;justify-content:center;height:745px;padding:30px 40px}.final-brand>img:first-child{width:300px}.final-brand>img:nth-child(2){width:100%;margin:25px 0}.color-bars{display:flex;width:290px;height:35px;gap:8px;margin-top:35px}.color-bars i{flex:1}.color-bars i:nth-child(1){background:#cfb77f}.color-bars i:nth-child(2){background:#faf6ef}.color-bars i:nth-child(3){background:#8b3653}.final h2{font-size:40px}.final p{font-size:25px}.final .small{font-size:18px}body.real .sheet{--s:1!important}@media(max-width:650px){nav{padding:0 15px;gap:12px;font-size:12px}nav .hide{display:none}main{padding:12px}.sheet{margin-bottom:12px}}@page{size:1800px 1100px;margin:0}@media print{body{background:none}nav{display:none}main{padding:0}.sheet{width:1800px!important;height:1100px!important;margin:0;break-after:page}.sheet:last-child{break-after:auto}.page{position:relative;transform:none!important}*{-webkit-print-color-adjust:exact;print-color-adjust:exact}}'''
html='<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Aurevi — bordô e ouro</title><style>'+css+'</style></head><body><nav><b>AUREVI</b><a href="#cores">Paleta</a><a href="#simbolo">AV</a><a href="#escrita">Escritas</a><a class="hide" href="#aplicacoes">Aplicações</a><span class="grow"></span><a href="Apresentacao-Aurevi-Bordo.pdf">PDF ↗</a></nav><main>'+''.join(pages)+'''</main><script>function fit(){document.documentElement.style.setProperty('--s',Math.min(1,(innerWidth-(innerWidth<650?24:56))/1800))}fit();addEventListener('resize',fit)</script></body></html>'''
(OUT/'APRESENTACAO.html').write_text(html,encoding='utf-8')
print('Apresentação para sócias criada:',len(pages),'páginas.')
